import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Scheme-Core Completeness for Self-Hosting","description":"","frontmatter":{"title":"Scheme-Core Completeness for Self-Hosting","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed\\n\\nGates [ADR-0044 — Language as Data and Runtime Split](./0044-language-as-data-and-runtime-split.md)\\nPhase 8 (self-hosting) and every downstream ADR that assumes handl can describe\\nitself as a `Language` value ([0064](./0064-computational-language-authoring.md),\\n[0065](./0065-derived-artifact-cache-and-compression.md),\\n[0066](./0066-dependency-graph-chunking.md),\\n[0067](./0067-chunk-certificates.md)). Refines\\n[ADR-0052 — Arrow Calculus Kernel](./0052-arrow-calculus-kernel.md) and\\n[ADR-0058 — Generic Data-Driven Engines](./0058-generic-data-driven-engines.md)."},"headers":[],"relativePath":"handl/project/adrs/0063-scheme-core-completeness.md","filePath":"vendored/handl/project/adrs/0063-scheme-core-completeness.md"}'),a={name:`handl/project/adrs/0063-scheme-core-completeness.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0063-scheme-core-completeness-for-self-hosting" tabindex="-1">ADR-0063: Scheme-Core Completeness for Self-Hosting <a class="header-anchor" href="#adr-0063-scheme-core-completeness-for-self-hosting" aria-label="Permalink to “ADR-0063: Scheme-Core Completeness for Self-Hosting”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-self-hosting-completeness-is-a-proven-property-not-an-aspiration" tabindex="-1">1. Self-hosting completeness is a proven property, not an aspiration <a class="header-anchor" href="#_1-self-hosting-completeness-is-a-proven-property-not-an-aspiration" aria-label="Permalink to “1. Self-hosting completeness is a proven property, not an aspiration”">​</a></h3><p>Before ADR-0044 Phase 8 is considered started, produce a <strong>completeness proof</strong>: a <code>handl-defining-handl</code> data file (or equivalent test artifact) that satisfies the three conditions above. The proof is a test, not a document — <code>self_host.rs</code> (already specified in ADR-0044 Phase 8 testing) is the artifact. This ADR adds the <strong>no-meta-<code>Foreign</code></strong> assertion to that test:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>assert!(capabilities(handl_language)</span></span>
<span class="line"><span>    .host_fns</span></span>
<span class="line"><span>    .iter()</span></span>
<span class="line"><span>    .all(|name| is_genuine_host_effect(name)));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;eval&quot;));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;parse&quot;));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;compile&quot;));</span></span></code></pre></div><p><code>is_genuine_host_effect</code> is defined as: the <code>Foreign</code> name refers to I/O, FFI, or capability-tracked host operations (ADR-0046), <strong>not</strong> to language machinery that belongs in the arrow core.</p><h3 id="_2-audit-and-eliminate-meta-foreign-escapes" tabindex="-1">2. Audit and eliminate meta-<code>Foreign</code> escapes <a class="header-anchor" href="#_2-audit-and-eliminate-meta-foreign-escapes" aria-label="Permalink to “2. Audit and eliminate meta-Foreign escapes”">​</a></h3><p>Inventory every <code>Foreign</code> tag in <code>eval.yaml</code>. Classify each as:</p><ul><li><strong>Genuine host effect</strong> (I/O, FFI, capability-tracked) — keep.</li><li><strong>Meta-operation masquerading as host function</strong> (<code>eval</code>, <code>parse</code>, <code>compile</code>, <code>var</code>-lookup, <code>call</code>-dispatch, key resolution) — eliminate by expressing it as arrow combinators or desugar rules.</li></ul><p>The elimination path for each meta-operation:</p><table tabindex="0"><thead><tr><th>Meta-operation</th><th>Elimination path</th></tr></thead><tbody><tr><td><code>eval</code> (recursive)</td><td><code>app</code> (ADR-0052 §2 — dynamic arrow invocation is the calculus operation, not a host call)</td></tr><tr><td><code>parse</code></td><td>Not an eval operation. Parse is a separate stage (ADR-0044 §2); a self-describing language&#39;s eval schemes never invoke parse.</td></tr><tr><td><code>compile</code></td><td><code>app</code> + handler interpretation (ADR-0052 §2 — external interpretation is the handler&#39;s job). <code>compile</code> as a host function is the Futamura specialization, not a language-internal operation.</td></tr><tr><td><code>var</code> lookup</td><td>Scope chain as arrow state threaded via <code>first</code>/<code>&gt;&gt;&gt;</code>; environments are values, not host lookups.</td></tr><tr><td><code>call</code> dispatch</td><td><code>app</code> (the callee is an arrow value; invocation is <code>app</code>).</td></tr><tr><td>Object key resolution</td><td>Desugar rule (ADR-0058 already specifies this migration).</td></tr></tbody></table><h3 id="_3-desugar-coverage-is-the-primary-completeness-mechanism" tabindex="-1">3. Desugar coverage is the primary completeness mechanism <a class="header-anchor" href="#_3-desugar-coverage-is-the-primary-completeness-mechanism" aria-label="Permalink to “3. Desugar coverage is the primary completeness mechanism”">​</a></h3><p>Surface constructs (<code>match</code>, <code>handle</code>, <code>pipe</code>, <code>ternary</code>, function literals, ...) lower to core combinators via desugar rules (data rewrites, ADR-0044 §4 &quot;Small core + desugar&quot;). The completeness proof requires that <strong>every surface construct in the canonical kit has a desugar rule to core combinators</strong>, with no construct falling back to a <code>Foreign</code> escape.</p><p>If a construct cannot be desugared without <code>Foreign</code>, that is evidence the core is incomplete — either extend the core (a new combinator, versioned per ADR-0044 §7 &quot;Scheme combinator versioning&quot;) or accept that the construct is not self-describable and document it as a known gap. Silently using <code>Foreign</code> is not acceptable.</p><h3 id="_4-the-conformance-suite-is-the-regression-gate" tabindex="-1">4. The conformance suite is the regression gate <a class="header-anchor" href="#_4-the-conformance-suite-is-the-regression-gate" aria-label="Permalink to “4. The conformance suite is the regression gate”">​</a></h3><p>ADR-0044&#39;s cross-engine conformance suite (<code>(Language, Ast, expected Value)</code> triples) is extended with a <strong>self-description corpus</strong>: triples where the <code>Language</code> is <code>handl-defining-handl</code> and the <code>Ast</code>/<code>Value</code> pairs exercise handl&#39;s own constructs. Every eval engine (tree-walk, bytecode, cranelift) must produce identical results on this corpus. A divergence is a self-hosting regression.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>ADR-0044 §&quot;Negative consequences&quot; names the single unsolved risk:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Self-hosting becomes a proven property, not a claim.</strong> The test either</li><li><strong>The boundary between language and host is sharp.</strong> <code>Foreign</code> means host</li><li><strong>Downstream ADRs are unblocked.</strong> Caching, chunking, and certificates</li><li><strong><code>app</code> is the sole meta-operation.</strong> <code>eval</code>/<code>compile</code> as host functions</li><li>**The completeness proof may fail, and fixing it may require core</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0063-scheme-core-completeness.html"><code>design/0063-scheme-core-completeness.md</code></a>.</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};